import json
Q=[];n=[0]
def add(goal,level,type,prompt,expl,**k):
    n[0]+=1;q={"id":f"W{n[0]:03d}","goal":goal,"level":level,"type":type,"prompt":prompt};q.update(k);q["explanation"]=expl;Q.append(q)
def mc(g,l,p,opts,a,e,**k):add(g,l,"mc",p,e,options=opts,answer=a,**k)
def tf(g,l,p,a,e,**k):add(g,l,"tf",p,e,answer=a,**k)
def num(g,l,p,a,tol,unit,e,**k):add(g,l,"num",p,e,answer=a,tolerance=tol,unit=unit,**k)
def order(g,l,p,items,e,**k):add(g,l,"order",p,e,items=items,**k)
def match(g,l,p,pairs,e,**k):add(g,l,"match",p,e,pairs=pairs,**k)
def cloze(g,l,p,text,gaps,e,**k):add(g,l,"cloze",p,e,text=text,gaps=gaps,**k)
def sel(opts,a):return {"options":opts,"answer":a}
def inp(a,alt=None):return {"answer":a,"alt":alt or []}
IMG=lambda f,alt,cr:{"src":"img/rzg-wk1/"+f,"alt":alt,"credit":cr}
PD="Wikimedia Commons, gemeinfrei"
