order(3,"E","Ordne die Kriegseintritte zeitlich.",["Osmanisches Reich (Mittelmächte)","Bulgarien (Mittelmächte)","Rumänien (Alliierte)","Griechenland (Alliierte)"],"Ende 1914, 1915, 1916, 1917.")
